73	static void rb_range_handle_of_ga_area(struct rbtree_node *node, struct rb_range_handle *range_handle)
74	{
75	    struct ga_area *area = rb_entry(node, struct ga_area, addr_tree_node);
76	
77	    range_handle->start = area->start;
78	    range_handle->end = area->start + area->size - 1;
