89	static struct ga_area *ga_alloc_area(u64 start, u64 size)
90	{
91	    struct ga_area *area = NULL;
92	
93	    area = svm_ua_calloc(1, sizeof(struct ga_area));
94	    if (area == NULL) {
95	        svm_err("svm_ua_calloc ga_area failed. (size=%llu)\n", sizeof(struct ga_area));
96	        return NULL;
97	    }
98	
99	    multi_rb_node_init(&area->size_tree_node);
100	    RB_CLEAR_NODE(&area->addr_tree_node);
101	    area->start = start;
102	    area->size = size;
103	    return area;
104	}
