106	static void ga_free_area(struct ga_area *area)
107	{
108	    svm_ua_free(area);
109	}
110	
111	static int ga_insert_area(struct ga_inst *inst, struct ga_range *range, struct ga_area *area)
112	{
113	    int ret;
114	
115	    area->inst = inst;
116	    area->range = range;
117	
118	    ret = rbtree_insert_by_range(&range->addr_area_tree, &area->addr_tree_node, rb_range_handle_of_ga_area);
119	    if (ret != 0) {
120	        return DRV_ERROR_INVALID_VALUE;
121	    }
122	    range->idle_area_size += area->size;
123	
124	    multi_rbtree_insert(area->size, &inst->size_area_tree, &area->size_tree_node);
125	    return DRV_ERROR_NONE;
126	}
