128	static void ga_erase_area(struct ga_area *area)
129	{
130	    area->range->idle_area_size -= area->size;
131	    multi_rbtree_erase(&area->inst->size_area_tree, &area->size_tree_node);
132	    _rbtree_erase(&area->range->addr_area_tree, &area->addr_tree_node);
133	
134	    area->inst = NULL;
135	    area->range = NULL;
136	}
