138	static struct ga_area *ga_create_area(struct ga_inst *inst, struct ga_range *range, u64 start, u64 size)
139	{
140	    struct ga_area *area = NULL;
141	    int ret;
142	
143	    area = ga_alloc_area(start, size);
144	    if (area == NULL) {
145	        return NULL;
146	    }
147	
148	    ret = ga_insert_area(inst, range, area);
149	    if (ret != DRV_ERROR_NONE) {
150	        ga_free_area(area);
151	        return NULL;
152	    }
153	
154	    return area;
155	}
