163	static struct ga_area *ga_get_area_by_size(struct ga_inst *inst, u64 size)
164	{
165	    struct ga_area *area = NULL;
166	    struct multi_rb_node *m_rb_node = NULL;
167	
168	    m_rb_node = multi_rbtree_get(size, &inst->size_area_tree);
169	    if (m_rb_node == NULL) {
170	        m_rb_node = multi_rbtree_get_upper_bound(size, &inst->size_area_tree);
171	    }
172	
173	    if (m_rb_node != NULL) {
174	        area = rb_entry(m_rb_node, struct ga_area, size_tree_node);
175	    }
176	
177	    return area;
178	}
