184	
185	    node = rbtree_search_by_range(&range->addr_area_tree, &rb_range, rb_range_handle_of_ga_area);
186	    if (node == NULL) {
187	        return NULL;
188	    }
189	
190	    return rb_entry(node, struct ga_area, addr_tree_node);
191	}
