197	    struct rb_range_handle rb_range = {.start = addr, .end = addr + size - 1};
198	
199	    node = rbtree_search_by_range(&inst->addr_range_tree, &rb_range, rb_range_handle_of_ga_range);
200	    if (node != NULL) {
