219	static void ga_try_slice_area(struct ga_area *area, u64 addr, u64 size)
220	{
221	    struct ga_inst *inst = area->inst;
222	    struct ga_range *range = area->range;
223	    struct ga_area *area_l = NULL;
224	    struct ga_area *area_r = NULL;
225	    u64 start_l, size_l, start_r, size_r;
226	    u64 area_start = area->start;
227	    u64 area_size = area->size;
228	
229	    ga_erase_area(area);
230	    if (area_size == size) {
231	        goto free_area;
232	    }
233	
234	    if (area_start < addr) {
235	        start_l = area_start;
236	        size_l = addr - area_start;
237	        area_l = ga_create_area(inst, range, start_l, size_l);
238	        if (area_l == NULL) {
239	            svm_info("Unlikely, unless out of memory. (start=0x%llx; size=%llu)\n", start_l, size_l);
240	        }
241	    }
242	
243	    if ((area_start + area_size) > (addr + size)) {
244	        start_r = addr + size;
245	        size_r = (area_start + area_size) - (addr + size);
246	        area_r = ga_create_area(inst, range, start_r, size_r);
247	        if (area_r == NULL) {
248	            svm_info("Unlikely, unless out of memory. (start=0x%llx; size=%llu)\n", start_r, size_r);
249	        }
250	    }
251	free_area:
252	    ga_free_area(area);
253	}
