255	static int ga_try_merge_area(struct ga_area *area)
256	{
257	    struct ga_inst *inst = area->inst;
258	    struct ga_range *range = area->range;
259	    struct ga_area *area_l = NULL;
260	    struct ga_area *area_r = NULL;
261	    u64 new_start = area->start;
262	    u64 new_size = area->size;
263	    int ret;
264	
265	    if (area->start > 0) {
266	        area_l = ga_range_get_area(range, area->start - 1, 1);
267	        if (area_l != NULL) {
268	            new_start = area_l->start;
269	            new_size += area_l->size;
270	            ga_erase_area(area_l);
271	            ga_free_area(area_l);
272	        }
273	    }
274	
275	    area_r = ga_range_get_area(range, area->start + area->size, 1);
276	    if (area_r != NULL) {
277	        new_size += area_r->size;
278	        ga_erase_area(area_r);
279	        ga_free_area(area_r);
280	    }
281	
282	    if (new_size != area->size) {
283	        ga_erase_area(area);
284	        area->start = new_start;
285	        area->size = new_size;
286	        ret = ga_insert_area(inst, range, area);
287	        if (ret != DRV_ERROR_NONE) {
288	            svm_err("Unlikely fail. (ret=%d; start=0x%llx; size=%llu)\n", ret, area->start, area->size);
289	            ga_free_area(area);
290	            return ret;
291	        }
292	    }
293	
294	    return DRV_ERROR_NONE;
295	}
