449	    (void)pthread_rwlock_init(&inst->rwlock, NULL);
450	    rbtree_init(&inst->addr_range_tree);
451	    rbtree_init(&inst->size_area_tree);
452	    inst->stats.range_num = 0;
453	
454	    return (void *)inst;
455	}
456	
457	void svm_ga_inst_destroy(void *ga_inst)
458	{
459	    struct ga_inst *inst = (struct ga_inst *)ga_inst;
460	
461	    ga_destroy_inst_all_range(inst);
462	
463	    svm_ua_free(inst);
464	}
465	
466	int svm_ga_add_range(void *ga_inst, u64 start, u64 size)
467	{
468	    struct ga_inst *inst = (struct ga_inst *)ga_inst;
469	    int ret;
470	
471	    if ((ga_addr_is_aligned(inst, start) == false) || (ga_addr_is_aligned(inst, size) == false)) {
472	        svm_err("Addr isn't aligned by order. (gran_size=%llu; start=0x%llx; size=%llu)\n", inst->attr.gran_size, start,
473	                size);
474	        return DRV_ERROR_INVALID_VALUE;
475	    }
476	
477	    pthread_rwlock_wrlock(&inst->rwlock);
478	    ret = ga_create_range(inst, start, size);
479	    pthread_rwlock_unlock(&inst->rwlock);
480	
481	    return ret;
482	}
483	
484	int svm_ga_del_range(void *ga_inst, u64 start)
485	{
486	    struct ga_inst *inst = (struct ga_inst *)ga_inst;
487	    struct ga_range *range = NULL;
488	
489	    (void)pthread_rwlock_wrlock(&inst->rwlock);
490	    range = ga_get_range(inst, start, 1);
491	    if (range == NULL) {
492	        (void)pthread_rwlock_unlock(&inst->rwlock);
493	        svm_err("No matched range. (start=0x%llx)\n", start);
494	        return DRV_ERROR_INVALID_VALUE;
495	    }
496	
497	    if (range->start != start) {
498	        svm_err("Start isn't matched with range_start. (start=0x%llx; range_start=0x%llx)\n", start, range->start);
499	        (void)pthread_rwlock_unlock(&inst->rwlock);
500	        return DRV_ERROR_INVALID_VALUE;
501	    }
502	
503	    if (ga_is_idle_range(range) == false) {
504	        svm_err("Range isn't idle. (start=0x%llx; size=%llu)\n", range->start, range->size);
505	        (void)pthread_rwlock_unlock(&inst->rwlock);
506	        return DRV_ERROR_INVALID_VALUE;
507	    }
508	
509	    ga_destroy_range(range);
510	    (void)pthread_rwlock_unlock(&inst->rwlock);
511	    return DRV_ERROR_NONE;
512	}
513	
514	int svm_ga_recycle_one_idle_range(void *ga_inst, u64 *start, u64 *size)
515	{
516	    struct ga_inst *inst = (struct ga_inst *)ga_inst;
517	    struct ga_range *range = NULL;
518	
519	    (void)pthread_rwlock_wrlock(&inst->rwlock);
520	    range = ga_get_one_idle_range(inst);
521	    if (range == NULL) {
522	        (void)pthread_rwlock_unlock(&inst->rwlock);
523	        return DRV_ERROR_NO_RESOURCES;
524	    }
525	
526	    *start = range->start;
527	    *size = range->size;
528	    ga_destroy_range(range);
529	    (void)pthread_rwlock_unlock(&inst->rwlock);
530	    return DRV_ERROR_NONE;
531	}
532	
533	int svm_ga_for_each_range(void *ga_inst, int (*func)(u64 start, u64 size, void *priv), void *priv)
534	{
535	    struct ga_inst *inst = (struct ga_inst *)ga_inst;
536	    struct ga_range *range = NULL;
537	    struct rbtree_node *cur = NULL;
538	    struct rbtree_node *n = NULL;
539	    int ret = 0;
540	
541	    (void)pthread_rwlock_rdlock(&inst->rwlock);
542	    rbtree_node_for_each_prev_safe(cur, n, &inst->addr_range_tree)
543	    {
544	        range = rb_entry(cur, struct ga_range, node);
545	        ret = func(range->start, range->size, priv);
546	        if (ret != DRV_ERROR_NONE) {
547	            break;
548	        }
549	    }
550	    (void)pthread_rwlock_unlock(&inst->rwlock);
551	    return ret;
552	}
553	
554	static int ga_alloc_by_fixed_addr(struct ga_inst *inst, u64 addr, u64 size)
555	{
556	    struct ga_area *area = NULL;
557	
558	    area = ga_get_area_by_addr(inst, addr, size);
559	    if (area == NULL) {
560	        return DRV_ERROR_PARA_ERROR;
561	    }
562	
563	    ga_try_slice_area(area, addr, size);
564	    return DRV_ERROR_NONE;
565	}
566	
567	static int ga_alloc_by_size(struct ga_inst *inst, u64 size, u64 *addr)
568	{
569	    struct ga_area *area = NULL;
570	
571	    area = ga_get_area_by_size(inst, size);
572	    if (area == NULL) {
573	        return DRV_ERROR_OUT_OF_MEMORY;
574	    }
575	
576	    *addr = area->start;
577	    ga_try_slice_area(area, *addr, size);
578	    return DRV_ERROR_NONE;
579	}
580	
581	static int ga_alloc_para_check(struct ga_inst *inst, u32 flag, u64 *addr, u64 size)
582	{
583	    if (ga_flag_is_fixed_addr(flag) && (ga_addr_is_aligned(inst, *addr) == false)) {
584	        svm_err("Add should aligned by gran_size. (addr=%llu; gran_size=%llu)\n", *addr, inst->attr.gran_size);
585	        return DRV_ERROR_PARA_ERROR;
586	    }
587	
588	    if (ga_addr_is_aligned(inst, size) == false) {
589	        svm_err("Size should aligned by gran_size. (size=%llu; gran_size=%llu)\n", size, inst->attr.gran_size);
590	        return DRV_ERROR_PARA_ERROR;
591	    }
592	
593	    if (size == 0) {
594	        return DRV_ERROR_PARA_ERROR;
595	    }
596	
597	    return DRV_ERROR_NONE;
598	}
599	
600	int svm_ga_alloc(void *ga_inst, u32 flag, u64 *addr, u64 size)
601	{
602	    struct ga_inst *inst = (struct ga_inst *)ga_inst;
603	    int ret;
604	
605	    ret = ga_alloc_para_check(inst, flag, addr, size);
606	    if (ret != DRV_ERROR_NONE) {
607	        return ret;
608	    }
609	
610	    (void)pthread_rwlock_wrlock(&inst->rwlock);
611	    if (ga_flag_is_fixed_addr(flag)) {
612	        ret = ga_alloc_by_fixed_addr(inst, *addr, size);
613	    } else if (ga_flag_is_in_fixed_addr_range(flag)) {
614	        ret = DRV_ERROR_NOT_SUPPORT;
615	    } else {
616	        ret = ga_alloc_by_size(inst, size, addr);
617	    }
618	    (void)pthread_rwlock_unlock(&inst->rwlock);
619	
620	    return ret;
621	}
622	
623	static int ga_free_para_check(struct ga_inst *inst, u64 addr, u64 size)
624	{
625	    if (ga_addr_is_aligned(inst, addr) == false) {
626	        svm_err("Add should aligned by gran_size. (addr=%llu; gran_size=%llu)\n", addr, inst->attr.gran_size);
627	        return DRV_ERROR_PARA_ERROR;
628	    }
629	
630	    if (ga_addr_is_aligned(inst, size) == false) {
631	        svm_err("Size should aligned by gran_size. (size=%llu; gran_size=%llu)\n", size, inst->attr.gran_size);
632	        return DRV_ERROR_PARA_ERROR;
633	    }
634	
635	    return DRV_ERROR_NONE;
636	}
637	
638	int svm_ga_free(void *ga_inst, u64 addr, u64 size)
639	{
640	    struct ga_inst *inst = (struct ga_inst *)ga_inst;
641	    struct ga_range *range = NULL;
642	    struct ga_area *area = NULL;
643	    int ret;
644	
645	    ret = ga_free_para_check(inst, addr, size);
646	    if (ret != DRV_ERROR_NONE) {
647	        return ret;
648	    }
649	
650	    (void)pthread_rwlock_wrlock(&inst->rwlock);
651	    range = ga_get_range(inst, addr, size);
652	    if (range == NULL) {
653	        (void)pthread_rwlock_unlock(&inst->rwlock);
654	        svm_err("No matched range. (addr=0x%llx; size=%llu)\n", addr, size);
655	        return DRV_ERROR_INVALID_VALUE;
656	    }
657	
658	    area = ga_create_area(inst, range, addr, size);
659	    if (area == NULL) {
660	        (void)pthread_rwlock_unlock(&inst->rwlock);
661	        svm_err("Create area failed. (addr=0x%llx; size=%llu)\n", addr, size);
662	        return DRV_ERROR_INVALID_VALUE;
663	    }
664	
665	    ret = ga_try_merge_area(area); // unlikely fail, if merge return fail, it will free area */
666	    (void)pthread_rwlock_unlock(&inst->rwlock);
667	
668	    return ret;
669	}
670	
671	u32 svm_ga_show(void *ga_inst, char *buf, u32 buf_len)
672	{
673	    SVM_UNUSED(ga_inst);
674	    SVM_UNUSED(buf);
675	    SVM_UNUSED(buf_len);
676	
677	    return 0;
678	}
