355	    normal_flag |= svm_flag_attr_is_va_without_master(flag) ? 0 : SVM_NORMAL_MALLOC_FLAG_VA_WITH_MASTER;
356	    normal_flag |= svm_flag_attr_is_master_uva(flag) ? SVM_NORMAL_MALLOC_FLAG_MASTER_UVA : 0;
357	    normal_flag |= svm_flag_attr_is_pg_rdonly(flag) ? SVM_NORMAL_MALLOC_FLAG_PG_RDONLY : 0;
