491	/* size: in alloc size, out actual alloced size by page align */
492	static int _svm_malloc(u64 *start, u64 *size, u64 align, u64 flag, struct svm_malloc_location *location,
493	                       bool *is_from_cache)
494	{
495	    u32 devid = location->devid;
496	    u32 numa_id = location->numa_id;
497	    u64 aligned_size;
498	    bool go_cache;
499	    int ret;
500	
501	    ret = get_aligned_size(devid, flag, align, *size, &aligned_size);
502	    if (ret != DRV_ERROR_NONE) {
503	        return ret;
504	    }
505	
506	    go_cache = go_malloc_cache(devid, numa_id, flag, align, aligned_size);
507	    if (go_cache) {
508	        ret = malloc_cache(devid, flag, align, aligned_size, start);
509	    } else {
510	        ret = malloc_normal(devid, numa_id, flag, align, aligned_size, start);
511	    }
512	    if (ret == DRV_ERROR_NONE) {
513	        *is_from_cache = go_cache;
514	        *size = aligned_size;
515	    }
516	
517	    return ret;
518	}
