559	static int malloc_align_matched_with_page_size_check(u32 devid, u64 flag, u64 align)
560	{
561	    u64 pg_size;
562	    int ret;
563	
564	    ret = svm_query_page_size_by_svm_flag(devid, flag, &pg_size);
565	    if (ret != DRV_ERROR_NONE) {
566	        svm_err("Query page size failed. (ret=%d; devid=%u; flag=0x%llx)\n", ret, devid, flag);
567	        return ret;
568	    }
569	
570	    if ((align % pg_size) != 0) {
571	        svm_err("Invalid align. (align=0x%llx; pg_size=0x%llx)\n", align, pg_size);
572	        return DRV_ERROR_INVALID_VALUE;
573	    }
574	
575	    /* Contiguous page is compound page, pg_num should be power of 2. */
576	    if (svm_flag_attr_is_contiguous(flag) && (svm_check_power_of_2(align / pg_size) != 0)) {
577	        svm_err("For contiguous, align/pg_size should be power of 2. (align=0x%llx; pg_size=0x%llx)\n", align, pg_size);
578	        return DRV_ERROR_INVALID_VALUE;
579	    }
580	
581	    return DRV_ERROR_NONE;
582	}
