584	static int malloc_para_check(u64 size, u64 align, u64 flag, struct svm_malloc_location *location)
585	{
586	    u64 range_start, range_size;
587	
588	    svm_get_va_range(&range_start, &range_size);
589	
590	    /* U64_MAX - xx will align to 0  */
591	    if (size > range_size) {
592	        return DRV_ERROR_OUT_OF_MEMORY;
593	    }
594	
595	    if (location->numa_id > SVM_MALLOC_NUMA_NO_NODE) {
596	        svm_err("Invalid numa id. (numa_id=%u)\n", location->numa_id);
597	        return DRV_ERROR_INVALID_VALUE;
598	    }
599	
600	    if (svm_flag_attr_is_va_only(flag)) {
601	        return DRV_ERROR_NONE;
602	    }
603	
604	    return malloc_align_matched_with_page_size_check(location->devid, flag, align);
605	}
