607	int svm_malloc(u64 *start, u64 size, u64 align, u64 flag, struct svm_malloc_location *location)
608	{
609	    u32 devid = location->devid;
610	    u64 aligned_size;
611	    handle_t *handle = NULL;
612	    struct svm_prop prop;
613	    bool is_from_cache;
614	    int ret;
615	
616	    ret = malloc_para_check(size, align, flag, location);
617	    if (ret != DRV_ERROR_NONE) {
618	        return ret;
619	    }
620	
621	    aligned_size = size;
622	    ret = _svm_malloc(start, &aligned_size, align, flag, location, &is_from_cache);
623	    if (ret != DRV_ERROR_NONE) {
624	        return ret;
625	    }
626	
627	    handle = handle_alloc();
628	    if (handle == NULL) {
629	        ret = DRV_ERROR_OUT_OF_MEMORY;
630	        goto free_mem;
631	    }
632	
633	    ret = svm_prop_pack(devid, flag, *start, size, is_from_cache, &prop);
634	    if (ret != DRV_ERROR_NONE) {
635	        goto free_handle;
636	    }
637	    prop.aligned_size = aligned_size;
638	
639	    handle_init(handle, &prop, is_from_cache, align);
640	
641	    ret = svm_mng_ops_post_malloc(handle, *start, &handle->prop);
642	    if (ret != DRV_ERROR_NONE) {
643	        goto uninit_handle;
644	    }
645	
646	    ret = handle_insert(handle);
647	    if (ret != DRV_ERROR_NONE) {
648	        goto ops_pre_free;
649	    }
650	
651	    return 0;
652	ops_pre_free:
653	    svm_mng_ops_pre_free(handle, *start, &handle->prop);
654	uninit_handle:
655	    (void)handle_uninit(handle, true);
656	free_handle:
657	    handle_free(handle);
658	free_mem:
659	    (void)_svm_free(devid, flag, align, *start, aligned_size, is_from_cache);
660	    return ret;
661	}
