663	int svm_free(u64 start)
664	{
665	    handle_t *handle = NULL;
666	    int ret;
667	
668	    ret = handle_erase(start, &handle);
669	    if (ret != DRV_ERROR_NONE) {
670	        return ret;
671	    }
672	
673	    ret = handle_uninit(handle, false);
674	    if (ret != DRV_ERROR_NONE) {
675	        handle_insert(handle);
676	        return ret;
677	    }
678	
679	    svm_mng_ops_pre_free(handle, start, &handle->prop);
680	
681	    ret = _svm_free(handle->prop.devid, handle->prop.flag, handle->align, handle->prop.start, handle->prop.aligned_size,
682	                    handle->is_from_cache);
683	    if (ret == DRV_ERROR_BUSY) {
684	        ret = handle_insert(handle);
685	        if (ret != DRV_ERROR_NONE) {
686	            handle_free(handle);
687	            svm_err("Unlikely insert failed.\n");
688	            return DRV_ERROR_INNER_ERR;
689	        }
690	        return DRV_ERROR_BUSY;
691	    } else {
692	        handle_free(handle);
693	    }
694	
695	    return ret;
696	}
