698	static int _svm_recycle_handle(handle_t *handle)
699	{
700	    int ret;
701	
702	    /* No need check handle->ref, force recycle. */
703	    _rbtree_erase(&mng.root, &handle->node);
704	
705	    ret = handle_uninit(handle, true);
706	    if (ret != DRV_ERROR_NONE) {
707	        _handle_insert(handle);
708	        return DRV_ERROR_INNER_ERR;
709	    }
710	
711	    ret = _svm_free(handle->prop.devid, handle->prop.flag, handle->align, handle->prop.start, handle->prop.aligned_size,
712	                    handle->is_from_cache);
713	    if (ret == DRV_ERROR_BUSY) {
714	        ret = _handle_insert(handle);
715	    } else {
716	        handle_free(handle);
717	    }
718	
719	    return DRV_ERROR_NONE;
720	}
