722	int svm_recycle_mem_by_dev(u32 devid)
723	{
724	    handle_t *handle = NULL;
725	    struct rbtree_node *cur = NULL;
726	    struct rbtree_node *n = NULL;
727	    int ret = DRV_ERROR_NONE;
728	    u32 recyle_num = 0;
729	
730	    pthread_rwlock_wrlock(&mng.rwlock);
731	    rbtree_node_for_each_prev_safe(cur, n, &mng.root)
732	    {
733	        handle = rb_entry(cur, handle_t, node);
734	        if ((devid == handle->prop.devid) || (devid == SVM_INVALID_DEVID)) {
735	            ret = _svm_recycle_handle(handle);
736	            if (ret != DRV_ERROR_NONE) {
737	                break;
738	            }
739	            recyle_num++;
740	        }
741	    }
742	    pthread_rwlock_unlock(&mng.rwlock);
743	
744	    if (recyle_num > 0) {
745	        svm_info("Recycle success. (devid=%u; recyle_num=%u)\n", devid, recyle_num);
746	    }
747	
748	    return ret;
749	}
