810	static int _svm_for_each_handle(int (*func)(void *handle, u64 start, struct svm_prop *prop, void *priv), void *priv,
811	                                bool check_valid)
812	{
813	    struct rbtree_node *cur = NULL;
814	    int ret = 0;
815	
816	    (void)pthread_rwlock_rdlock(&mng.rwlock);
817	    rbtree_node_for_each(cur, &mng.root)
818	    {
819	        handle_t *handle = rb_entry(cur, handle_t, node);
820	        if (check_valid && !handle_is_match_state((handle_t *)handle, HANDLE_STATE_INITED)) {
821	            continue;
822	        }
823	        ret = func((void *)handle, handle->prop.start, &handle->prop, priv);
824	        if (ret != 0) {
825	            break;
826	        }
827	    }
828	    pthread_rwlock_unlock(&mng.rwlock);
829	    return ret;
830	}
