857	int svm_get_nearby_prop(u64 va, struct svm_prop *left_prop, bool *has_left, struct svm_prop *right_prop,
858	                        bool *has_right)
859	{
860	    struct rbtree_node *left_node = NULL;
861	    struct rbtree_node *right_node = NULL;
862	    struct rbtree_node *upper = NULL;
863	    int ret;
864	
865	    if ((left_prop == NULL) || (has_left == NULL) || (right_prop == NULL) || (has_right == NULL)) {
866	        return DRV_ERROR_INVALID_VALUE;
867	    }
868	
869	    *has_left = false;
870	    *has_right = false;
871	
872	    pthread_rwlock_rdlock(&mng.rwlock);
873	    upper = rbtree_search_upper_bound_range(&mng.root, va, rb_range_of_handle);
874	    left_node = (upper != NULL) ? rbtree_prev(upper) : rbtree_last(&mng.root);
875	    right_node = upper;
876	
877	    while (left_node != NULL) {
878	        handle_t *left_handle = rb_entry(left_node, handle_t, node);
879	
880	        if (handle_is_match_state(left_handle, HANDLE_STATE_INITED)) {
881	            ret = handle_get_prop(left_handle, left_handle->prop.start, left_prop);
882	            if (ret == DRV_ERROR_NONE) {
883	                *has_left = true;
884	                break;
885	            }
886	        }
887	        left_node = rbtree_prev(left_node);
888	    }
889	
890	    while (right_node != NULL) {
891	        handle_t *right_handle = rb_entry(right_node, handle_t, node);
892	
893	        if (handle_is_match_state(right_handle, HANDLE_STATE_INITED)) {
894	            ret = handle_get_prop(right_handle, right_handle->prop.start, right_prop);
895	            if (ret == DRV_ERROR_NONE) {
896	                *has_right = true;
897	                break;
898	            }
899	        }
900	        right_node = rbtree_next(right_node);
901	    }
902	    pthread_rwlock_unlock(&mng.rwlock);
903	
904	    return DRV_ERROR_NONE;
905	}
