1037	    u32 normal_flag = svm_flag_to_normal_flag(prop->flag, SVM_MALLOC_NUMA_NO_NODE) |
1038	                      SVM_NORMAL_MALLOC_FLAG_POPULATE_ONLY;
1039	    u32 devid = *(u32 *)priv;
1040	    int tgid, ret;
1041	
1042	    if (devid != prop->devid) {
1043	        return DRV_ERROR_NONE;
1044	    }
1045	
1046	    ret = svm_get_dev_tgid(devid, &tgid);
1047	    if (ret != DRV_ERROR_NONE) {
1048	        return ret;
1049	    }
1050	    svm_mod_prop_tgid(handle, tgid);
1051	
1052	    if (!prop->is_from_cache) {
1053	        ret = svm_normal_malloc(devid, normal_flag, handle->align, &start, prop->aligned_size);
1054	        if (ret != DRV_ERROR_NONE) {
1055	            svm_err("Recover handle pa failed. (ret=%d; devid=%u; flag=0x%llx; start=0x%llx; size=%llu)\n", ret,
1056	                    prop->devid, prop->flag, start, prop->aligned_size);
