1062	            svm_err("Post malloc operation failed. (ret=%d; devid=%u; start=0x%llx; size=%llu)\n", ret, devid, start,
1063	                    prop->aligned_size);
1064	            (void)svm_normal_free(devid, normal_flag, handle->align, start, prop->aligned_size);
