1072	int svm_malloc_mng_criu_restore(u32 devid, void *data)
1073	{
1074	    SVM_UNUSED(data);
1075	    return svm_for_each_valid_handle(svm_handle_recover_pa, &devid);
1076	}
1077	
1078	static const struct svm_criu_ops g_malloc_mng_criu_ops = {
1079	    .name = "malloc_mng",
1080	    .reset = svm_malloc_mng_criu_reset,
1081	    .restore = svm_malloc_mng_criu_restore,
1082	};
1083	
1084	void __attribute__((constructor(SVM_INIT_PRI_FINAL - 2))) svm_mng_init(void)
1085	{
1086	    int ret;
1087	
1088	    ret = svm_register_ioctl_dev_init_post_handle(svm_malloc_mng_dev_init);
1089	    if (ret != DRV_ERROR_NONE) {
1090	        svm_err("Register ioctl dev init post handle failed. \n");
1091	    }
1092	
