56	static void cache_strategy_update(struct cache_allocator *ca)
57	{
58	    u64 shrink_thres_default, cur_alloced, peak_alloced;
59	
60	    pthread_rwlock_wrlock(&ca->rwlock);
61	    shrink_thres_default = ca->strategy.shrink_thres_default;
62	    cur_alloced = ca->stats.cur_alloced;
63	    peak_alloced = ca->stats.peak_alloced;
64	    ca->strategy.shrink_thres_cur = svm_max(svm_min(2ull * cur_alloced, (peak_alloced + cur_alloced) / 2ull),
65	                                            shrink_thres_default); /* multiple is 2, peak_alloced's weight is 1/2 */
66	    pthread_rwlock_unlock(&ca->rwlock);
67	}
68	
69	static void cache_malloc_stats_update(struct cache_allocator *ca, u64 size)
70	{
71	    time_t cur_time = time(NULL);
72	
73	    pthread_rwlock_wrlock(&ca->rwlock);
74	    ca->stats.idle -= size;
75	    ca->stats.cur_alloced += size;
76	    if (ca->stats.cur_alloced > ca->stats.peak_alloced) {
77	        ca->stats.peak_alloced = ca->stats.cur_alloced;
78	        ca->stats.peak_alloced_last_update_time = cur_time;
79	    }
80	    if ((u64)(cur_time - ca->stats.peak_alloced_last_update_time) >= CACHE_MALLOC_PEAK_ALLOCED_TIME_INTERVAL_S) {
81	        u64 tmp_size = ca->stats.peak_alloced -
82	                       ca->stats.peak_alloced / 8; /* peak bigger than cur 1/8 refresh cache thres */
83	        if (tmp_size > ca->stats.cur_alloced) {
84	            ca->stats.peak_alloced = tmp_size;
85	            ca->stats.peak_alloced_last_update_time = cur_time;
86	        }
87	    }
88	    pthread_rwlock_unlock(&ca->rwlock);
89	}
90	
91	static void cache_free_stats_update(struct cache_allocator *ca, u64 size)
92	{
93	    time_t cur_time = time(NULL);
94	
95	    pthread_rwlock_wrlock(&ca->rwlock);
96	    ca->stats.idle += size;
97	    ca->stats.cur_alloced -= size;
98	    if ((u64)(cur_time - ca->stats.peak_alloced_last_update_time) >= CACHE_MALLOC_PEAK_ALLOCED_TIME_INTERVAL_S) {
99	        ca->stats.peak_alloced = ca->stats.cur_alloced;
100	    }
