215	    u64 start, size;
216	    int ret;
217	
218	    ret = svm_ga_recycle_one_idle_range(ca->ga_inst, &start, &size);
219	    if (ret != DRV_ERROR_NONE) {
220	        return ret;
221	    }
222	
223	    cache_shrink_stats_update(ca, size);
224	
225	    ret = cache_shrink(ca, start, size);
226	    if (ret == DRV_ERROR_BUSY) {
227	        cache_recycle_add_seg(start, size, align, ca->devid, ca->flag);
228	    }
229	
230	    *out_size = (ret == DRV_ERROR_NONE) ? size : 0;
231	    return ((ret == DRV_ERROR_BUSY) ? DRV_ERROR_NONE : ret);
232	}
233	
234	static int cache_malloc(struct cache_allocator *ca, u64 *va, u64 size)
235	{
236	    u64 expand_size;
237	    int ret;
238	
239	    ret = _cache_malloc(ca, va, size);
240	    while (ret == DRV_ERROR_OUT_OF_MEMORY) {
241	        expand_size = svm_align_up(svm_align_up(size, ca->strategy.expand_granularity), ca->strategy.alloc_gran);
242	        ret = cache_expand_once(ca, expand_size);
243	        if (ret != DRV_ERROR_NONE) {
244	            return ret;
245	        }
246	
247	        /* Might be alloced by other threads, should retry. */
248	        ret = _cache_malloc(ca, va, size);
249	    }
250	
251	    return ret;
252	}
253	
254	static int cache_free(struct cache_allocator *ca, u64 va, u64 size)
255	{
256	    u64 shrink_size = 0;
257	    int ret;
258	
259	    ret = _cache_free(ca, va, size);
260	    if (ret != DRV_ERROR_NONE) {
261	        return ret;
262	    }
263	
264	    cache_strategy_update(ca);
265	
266	    if (cache_try_shrink(ca, va)) {
267	        while (cache_should_shrink(ca)) {
268	            ret = cache_shrink_once(ca, &shrink_size);
269	            if ((ret != DRV_ERROR_NONE) && (ret != DRV_ERROR_BUSY)) {
270	                break;
271	            }
272	        }
273	    }
274	
275	    return DRV_ERROR_NONE;
276	}
277	
278	bool svm_cache_is_support(u32 devid, u32 flag, u64 align, u32 size)
279	{
280	    struct cache_allocator *ca = NULL;
281	
282	    ca = cache_get_allocator(devid, flag);
283	    return (((ca != NULL) && (size <= ca->strategy.alloc_thres) && (align == ca->strategy.alloc_gran)) ? true : false);
284	}
285	
286	int svm_cache_malloc(u32 devid, u32 flag, u64 align, u64 *va, u64 size)
287	{
288	    struct cache_allocator *ca = NULL;
289	
290	    ca = cache_get_allocator(devid, flag);
291	    if (ca == NULL) {
292	        svm_err("Get cache allocator failed. (devid=%u; flag=0x%x)\n", devid, flag);
293	        return DRV_ERROR_INNER_ERR;
294	    }
295	
296	    if (align != ca->strategy.alloc_gran) {
297	        svm_err("Cur cache flag not support such align. (devid=%u; flag=0x%x; align=%llu)\n", devid, flag, align);
298	        return DRV_ERROR_INVALID_VALUE;
299	    }
300	
301	    return cache_malloc(ca, va, size);
302	}
303	
304	int svm_cache_free(u32 devid, u32 flag, u64 align, u64 va, u64 size)
305	{
306	    struct cache_allocator *ca = NULL;
307	
308	    ca = cache_get_allocator(devid, flag);
309	    if (ca == NULL) {
310	        svm_err("Get cache allocator failed. (devid=%u; flag=0x%x)\n", devid, flag);
311	        return DRV_ERROR_INNER_ERR;
312	    }
313	
314	    if (align != ca->strategy.alloc_gran) {
315	        svm_err("Cur cache flag not support such align. (devid=%u; flag=0x%x; align=%llu)\n", devid, flag, align);
316	        return DRV_ERROR_INVALID_VALUE;
317	    }
318	
319	    return cache_free(ca, va, size);
320	}
321	
322	void svm_cache_shrink(u32 devid, u32 flag, u64 *size)
323	{
324	    struct cache_allocator *ca = NULL;
325	    u64 shrink_size = 0;
326	    int ret;
327	
328	    *size = 0;
329	    ca = cache_get_allocator(devid, flag);
330	    if (ca == NULL) {
331	        return;
332	    }
333	
334	    do {
335	        ret = cache_shrink_once(ca, &shrink_size);
336	        *size += (ret == DRV_ERROR_NONE) ? shrink_size : 0;
337	    } while (ret == DRV_ERROR_NONE);
338	}
