10	#include <pthread.h>
11	
12	#include "securec.h"
13	
14	#include "rbtree.h"
15	
16	#include "svm_log.h"
17	#include "cache_pub.h"
18	#include "cache_recycle_seg.h"
19	
20	struct cache_recycle_seg {
21	    struct rbtree_node node;
22	
23	    u64 start;
24	    u64 size;
25	    u64 align;
26	    u32 flag;
27	    u32 devid;
28	};
29	
30	static pthread_rwlock_t g_rwlock = PTHREAD_RWLOCK_INITIALIZER;
31	static struct rbtree_root g_rb_root = RB_ROOT;
32	
33	static void rb_range_handle_of_cache_recycle_seg(struct rbtree_node *node, struct rb_range_handle *range_handle)
34	{
35	    struct cache_recycle_seg *seg = rb_entry(node, struct cache_recycle_seg, node);
36	
37	    range_handle->start = seg->start;
38	    range_handle->end = seg->start + seg->size - 1;
39	}
40	
41	void cache_recycle_add_seg(u64 start, u64 size, u64 align, u32 devid, u32 flag)
42	{
43	    struct cache_recycle_seg *seg = NULL;
44	    int ret;
45	
46	    seg = calloc(1, sizeof(struct cache_recycle_seg));
47	    if (seg == NULL) {
48	        svm_warn("Calloc cache_recycle_seg check. (size=%llu)\n", sizeof(struct cache_recycle_seg));
49	        return;
50	    }
51	
52	    RB_CLEAR_NODE(&seg->node);
53	    seg->start = start;
54	    seg->size = size;
55	    seg->align = align;
56	    seg->flag = flag;
57	    seg->devid = devid;
58	
59	    (void)pthread_rwlock_wrlock(&g_rwlock);
60	    ret = rbtree_insert_by_range(&g_rb_root, &seg->node, rb_range_handle_of_cache_recycle_seg);
61	    (void)pthread_rwlock_unlock(&g_rwlock);
62	    if (ret != DRV_ERROR_NONE) {
63	        svm_warn("Insert recycle seg node check. (start=0x%llx; size=%llu)\n", start, size);
64	        free(seg);
65	    }
66	}
67	
68	static int cache_recycle_del_seg(u64 start, u64 *size, u64 *align, u32 *devid, u32 *flag)
69	{
70	    struct cache_recycle_seg *seg = NULL;
71	    struct rbtree_node *rb_node = NULL;
72	    struct rb_range_handle range = {.start = start, .end = start};
73	
74	    (void)pthread_rwlock_wrlock(&g_rwlock);
75	    rb_node = rbtree_search_by_range(&g_rb_root, &range, rb_range_handle_of_cache_recycle_seg);
76	    if (rb_node == NULL) {
77	        (void)pthread_rwlock_unlock(&g_rwlock);
78	        return DRV_ERROR_NOT_EXIST;
79	    }
80	
81	    seg = rb_entry(rb_node, struct cache_recycle_seg, node);
82	    if (start != seg->start) {
83	        (void)pthread_rwlock_unlock(&g_rwlock);
84	        return DRV_ERROR_NOT_EXIST;
85	    }
86	    _rbtree_erase(&g_rb_root, &seg->node);
87	
88	    *size = seg->size;
89	    *align = seg->align;
90	    *devid = seg->devid;
91	    *flag = seg->flag;
92	    free(seg);
93	    (void)pthread_rwlock_unlock(&g_rwlock);
94	    return DRV_ERROR_NONE;
95	}
96	
97	int svm_cache_recycle_seg_release(u64 va)
98	{
99	    u32 devid, flag, normal_flag;
100	    u64 size, align;
101	    int ret;
102	
103	    ret = cache_recycle_del_seg(va, &size, &align, &devid, &flag);
104	    if (ret != DRV_ERROR_NONE) {
105	        return ret;
106	    }
107	
108	    normal_flag = cache_flag_to_normal_flag(flag);
109	    return svm_normal_free(devid, normal_flag, align, va, size);
110	}
111	
112	static u32 _cache_recyle_seg_show(struct cache_recycle_seg *seg, int id, char *buf, u32 buf_len)
113	{
114	    if (buf == NULL) {
115	        svm_info("recycle seg id %d: flag=0x%x start=0x%llx size=0x%llx\n", id, seg->flag, seg->start, seg->size);
116	        return 0;
117	    } else {
118	        if (buf_len == 0) {
119	            return 0;
120	        }
121	        int len;
122	
123	        len = snprintf_s(buf, buf_len, buf_len - 1, "recycle seg id %d: flag=0x%x start=0x%llx size=0x%llx\n", id,
124	                         seg->flag, seg->start, seg->size);
125	        return (len < 0) ? 0 : (u32)len;
126	    }
127	}
128	
129	u32 cache_recycle_seg_show(u32 devid, char *buf, u32 buf_len)
130	{
131	    struct cache_recycle_seg *seg = NULL;
132	    struct rbtree_node *cur = NULL;
133	    int id = 0;
134	    u32 len = 0;
135	
136	    (void)pthread_rwlock_rdlock(&g_rwlock);
137	    rbtree_node_for_each(cur, &g_rb_root)
138	    {
139	        seg = rb_entry(cur, struct cache_recycle_seg, node);
140	        if ((devid == seg->devid) || (devid == SVM_INVALID_DEVID)) {
141	            len += _cache_recyle_seg_show(seg, id++, buf + len, buf_len - len);
142	        }
143	    }
144	    (void)pthread_rwlock_unlock(&g_rwlock);
145	
146	    return len;
147	}
148	
149	static void _cache_recycle_seg_clear_by_dev(u32 devid)
150	{
151	    struct cache_recycle_seg *seg = NULL;
