73	
74	    /* dev cp only can not be specified va */
75	    if ((flag & SVM_VA_ALLOCATOR_FLAG_DEV_CP_ONLY) != 0) {
76	        svm_err("Specified flag dev cp only. (flag=%x)\n", flag);
77	        return VA_ALLOCATOR_TYPE_UNKNOWN;
