93	u32 svm_get_non_spacified_va_allocator_type(u64 va, u64 size, u32 devid, u32 flag)
94	{
95	    SVM_UNUSED(va);
96	
97	    if ((flag & SVM_VA_ALLOCATOR_FLAG_DEV_CP_ONLY) != 0) {
98	        /* dev cp only can not with master */
99	        if ((flag & SVM_VA_ALLOCATOR_FLAG_WITH_MASTER) != 0) {
100	            svm_err("Dev cp only with master. (flag=%x)\n", flag);
101	            return VA_ALLOCATOR_TYPE_UNKNOWN;
102	        }
103	
104	        return VA_ALLOCATOR_TYPE_DEV_CP_ONLY;
105	    }
106	
107	    if (((flag & SVM_VA_ALLOCATOR_FLAG_MASTER_UVA) != 0) && (svm_is_support_pcie_th())) {
108	        return VA_ALLOCATOR_TYPE_PCIE_TH;
109	    }
110	
111	    /* use default when not specified va but has no master or size is too bigger */
112	    if ((flag & SVM_VA_ALLOCATOR_FLAG_WITH_MASTER) == 0) {
113	        return VA_ALLOCATOR_TYPE_DEFAULT;
114	    }
115	
116	    if (devid == SVM_INVALID_DEVID) {
117	        return (size > NON_DEV_DEFAULT_ALLOC_MAX_SIZE) ? VA_ALLOCATOR_TYPE_DEFAULT : VA_ALLOCATOR_TYPE_NON_DEV_DEFAULT;
118	    }
119	
120	    return VA_ALLOCATOR_TYPE_DEV_DEFAULT;
