123	u32 svm_get_va_allocator_type(u64 va, u64 size, u32 devid, u32 flag, int op)
124	{
125	    if ((flag & SVM_VA_ALLOCATOR_FLAG_MASTER_UVA) != 0) {
126	        if ((flag & SVM_VA_ALLOCATOR_FLAG_WITH_MASTER) == 0) {
127	            svm_err("Master uva must with master. (va=0x%llx; flag=%x)\n", va, flag);
128	            return VA_ALLOCATOR_TYPE_UNKNOWN;
