132	    if ((flag & SVM_VA_ALLOCATOR_FLAG_WITHOUT_POPULATE) != 0) {
133	        return VA_ALLOCATOR_TYPE_VA_ONLY_WITHOUT_POPULATE;
134	    }
135	
136	    if ((flag & SVM_VA_ALLOCATOR_FLAG_SPACIFIED_ADDR) != 0) {
137	        if ((op == 1) && (va == 0)) {
138	            svm_err("Specified flag but va is null. (va=0x%llx; flag=%x)\n", va, flag);
139	            return VA_ALLOCATOR_TYPE_UNKNOWN;
