143	    } else {
144	        if ((op == 1) && (va != 0)) {
145	            svm_err("No specified flag but va is not null. (va=0x%llx; flag=%x)\n", va, flag);
146	            return VA_ALLOCATOR_TYPE_UNKNOWN;
