153	int svm_alloc_va(u64 va, u64 size, u64 align, u32 devid, u32 flag, u64 *start)
154	{
155	    u32 allocator_type = svm_get_va_allocator_type(va, size, devid, flag, 1);
156	    u32 reserve_flag = 0;
157	    int ret;
158	
159	    if (size == 0) {
160	        svm_debug("Invalid size. (size=0x%llx)\n", size);
161	        /* It's not appropriate, we have to inherit the existing error codes. */
162	        return DRV_ERROR_OUT_OF_MEMORY;
163	    }
164	
165	    switch (allocator_type) {
166	        case VA_ALLOCATOR_TYPE_DEV_DEFAULT:
167	            return va_dev_default_alloc(devid, align, size, start);
168	        case VA_ALLOCATOR_TYPE_NON_DEV_DEFAULT:
169	            return va_non_dev_default_alloc(align, size, start);
170	        case VA_ALLOCATOR_TYPE_DEV_CP_ONLY:
171	            return va_dev_cp_only_alloc(devid, align, size, start);
172	        case VA_ALLOCATOR_TYPE_DEV_DCACHE:
173	            ret = va_dev_dcache_alloc(va, size);
174	            if (ret == 0) {
175	                *start = va;
176	            }
177	            return ret;
178	        case VA_ALLOCATOR_TYPE_PCIE_TH:
179	            return va_pcie_th_alloc(devid, align, size, start);
180	        case VA_ALLOCATOR_TYPE_DEFAULT:
181	            reserve_flag |= SVM_VA_RESERVE_FLAG_WITH_CUSTOM_CP;
182	            reserve_flag |= SVM_VA_RESERVE_FLAG_WITH_HCCP;
183	
184	            if ((flag & SVM_VA_ALLOCATOR_FLAG_WITH_MASTER) != 0) {
185	                reserve_flag |= SVM_VA_RESERVE_FLAG_WITH_MASTER;
186	            }
187	
188	            return svm_reserve_va(va, size + svm_align_up(svm_va_get_gap(), SVM_VA_RESERVE_ALIGN), reserve_flag, start);
189	        case VA_ALLOCATOR_TYPE_VA_ONLY_WITHOUT_POPULATE:
190	            return va_only_without_populate_alloc(devid, align, size, start);
191	        default:
192	            svm_err("Invalid para. (va=0x%llx size=0x%llx; devid=%u; flag=%x)\n", va, size, devid, flag);
