209	        case VA_ALLOCATOR_TYPE_NON_DEV_DEFAULT:
210	            return va_non_dev_default_free(va, size, align);
211	        case VA_ALLOCATOR_TYPE_DEV_CP_ONLY:
212	            return va_dev_cp_only_free(devid, va, size);
213	        case VA_ALLOCATOR_TYPE_DEV_DCACHE:
214	            return va_dev_dcache_free(va, size);
215	        case VA_ALLOCATOR_TYPE_PCIE_TH:
216	            return va_pcie_th_free(devid, va, size, align);
217	        case VA_ALLOCATOR_TYPE_DEFAULT:
