227	static int svm_va_allocator_dev_init(u32 devid)
228	{
229	    int ret;
230	
231	    ret = va_dev_default_allocator_dev_init(devid);
232	    if (ret != DRV_ERROR_NONE) {
233	        return ret;
234	    }
235	
236	    ret = va_reserve_add_dev(devid);
237	    if (ret != DRV_ERROR_NONE) {
238	        va_dev_default_allocator_dev_uninit(devid);
239	        return ret;
240	    }
241	
242	    if (devid == svm_get_host_devid()) {
243	        return DRV_ERROR_NONE;
244	    }
245	
246	    ret = va_dev_dcache_allocator_init();
247	    if (ret != DRV_ERROR_NONE) {
248	        va_reserve_del_dev(devid);
249	        va_dev_default_allocator_dev_uninit(devid);
250	        return ret;
251	    }
252	
253	    ret = va_dev_linear_mem_enable();
254	    if (ret != DRV_ERROR_NONE) {
255	        /* not rollback dcache */
256	        va_reserve_del_dev(devid);
257	        va_dev_default_allocator_dev_uninit(devid);
258	        return ret;
259	    }
260	
261	    return DRV_ERROR_NONE;
262	}
263	
264	static int svm_va_allocator_dev_uninit(u32 devid)
265	{
266	    va_dev_default_allocator_dev_uninit(devid);
267	
268	    if (devid == svm_get_host_devid()) {
269	        return DRV_ERROR_NONE;
270	    }
271	
272	    va_reserve_del_dev(devid);
273	    return DRV_ERROR_NONE;
274	}
