276	static int svm_va_allocator_criu_reset_dev(u32 devid, void *data)
277	{
278	    SVM_UNUSED(data);
279	    va_reserve_del_dev(devid);
280	    return 0;
281	}
282	
283	static const struct svm_criu_ops g_va_allocator_criu_ops = {
284	    .name = "va_allocator",
285	    .reset = svm_va_allocator_criu_reset_dev,
286	};
287	
288	void __attribute__((constructor(SVM_INIT_PRI_HIGH))) svm_va_allocator_init(void)
289	{
290	    int ret;
291	
292	    ret = svm_register_ioctl_dev_init_post_handle(svm_va_allocator_dev_init);
293	    if (ret != DRV_ERROR_NONE) {
294	        svm_err("Register ioctl dev init post handle failed.\n");
295	    }
296	
297	    ret = svm_register_ioctl_dev_uninit_pre_handle(svm_va_allocator_dev_uninit);
298	    if (ret != DRV_ERROR_NONE) {
299	        svm_err("Register ioctl dev uninit post handle failed.\n");
300	    }
301	
302	    ret = svm_criu_register_ops(&g_va_allocator_criu_ops);
303	    if (ret != DRV_ERROR_NONE) {
304	        svm_err("Register CRIU ops failed.\n");
305	    }
306	}
307	
308	void svm_va_allocator_uninit(void)
309	{
310	    va_non_dev_default_allocator_uninit();
311	    va_pcie_th_allocator_uninit();
312	    va_dev_cp_only_allocator_uninit();
313	    va_dev_linear_mem_disable();
314	    va_dev_dcache_allocator_uninit();
315	    va_only_without_populate_allocator_uninit();
316	}
